#!/usr/bin/env bash
# Regenerate the library root `Zeta.lean`: a `public import` of every module under `Zeta/`, like
# Mathlib's `mk_all`, except the generated certificate files.
#
#   scripts/mk_all.sh     # rewrite Zeta.lean (after adding, moving or deleting a module)
#   scripts/mk_all.sh --check   # write nothing; fail, printing the difference, if Zeta.lean is stale (CI)
#
# Left out: generated files (an `AUTO-GENERATED by` header) inside a `Certificates/` subdirectory,
# i.e. the batch and group modules `gen_zero_certificates.py` writes under
# `Zeta/Zeros/Certificates/<subdirectory>/`. Their names and number change with every
# regeneration, and the assembler `Zeta.Zeros.Certificates` imports them all, so the root names
# none of them and never goes stale when the certificates are regenerated or pruned. Generated
# files with fixed names (the assembler, `Zeta.Zeros.CountCertificates`, `Zeta.Gram.Certificates`)
# are listed as usual.
set -euo pipefail
cd "$(dirname "$0")/.."

lib=Zeta
check=0
case "${1:-}" in
  --check) check=1 ;;
  "") ;;
  *) echo "usage: scripts/mk_all.sh [--check]" >&2; exit 2 ;;
esac

render() {
  cat <<'EOF'
/-
The `Zeta` library root: every module under `Zeta/` except the generated certificate
files, which `Zeta.Zeros.Certificates` imports. Use `scripts/mk_all.sh` to generate rather
than `lake exe mk_all`.
-/
module

EOF
  # every module less the generated ones, found by one `grep` over all of `Certificates/`, since a
  # large height has millions of batch files
  LC_ALL=C comm -23 \
    <(find "$lib" -name '*.lean' | LC_ALL=C sort) \
    <(find "$lib" -path '*/Certificates/*' -name '*.lean' -print0 \
        | { xargs -0 grep -l 'AUTO-GENERATED by' || true; } | LC_ALL=C sort) \
    | sed -e 's/\.lean$//' -e 's|/|.|g' -e 's/^/public import /' | LC_ALL=C sort
}

tmp=$lib.lean.tmp
trap 'rm -f "$tmp"' EXIT
render > "$tmp"
if (( check )); then
  if ! diff -u --label "$lib.lean" --label "$lib.lean (expected)" "$lib.lean" "$tmp"; then
    echo "$lib.lean is out of date: run scripts/mk_all.sh" >&2
    exit 1
  fi
  echo "$lib.lean: up to date"
else
  mv "$tmp" "$lib.lean"
  echo "$lib.lean: wrote $(grep -c '^public import' "$lib.lean") imports"
fi
